@Injectable()
export class JobScheduler {
  private readonly logger = new Logger(JobScheduler.name);

  constructor(
    @InjectRepository(InventoryReservation) private readonly inventoryReservationRepository: EntityRepository<InventoryReservation>,
    @InjectRepository(Product) private readonly productRepository: EntityRepository<Product>,
    private readonly productDbEm: EntityManager,
  ) {}

  @Cron(JOB_CONFIGS['ReleaseExpiredReservations'].schedule, { timeZone: process.env.TZ || 'UTC' })
  async runReleaseExpiredReservations(): Promise<void> {
    const config = JOB_CONFIGS['ReleaseExpiredReservations'];
    const startTime = Date.now();
    this.logger.log('job_started name=ReleaseExpiredReservations');

    let lastError: Error | undefined;
    for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), config.timeoutSeconds * 1000);
      try {
let expired: InventoryReservation[] = await (this.inventoryReservationRepository.getEntityManager() as SqlEntityManager).createQueryBuilder(InventoryReservation, 'e_inventory_reservation').select('*').where('e_inventory_reservation.status = ?', [ReservationStatus.Reserved]).andWhere('e_inventory_reservation.expires_at < ?', [new Date()]).getResultList();
        let reservationGroups: Record<string, any> = {};
        for (const reservation of expired) {
          let key: string = String(reservation.reservationId);
          if ((reservationGroups[key] == null)) {
            reservationGroups[key] = [];
          }
          reservationGroups[key].push(reservation);
        }
        let count: number = 0;
        for (const reservationId of Object.keys(reservationGroups)) {
          let batch: Record<string, any> = reservationGroups[reservationId];
          await bufferEvents(async () => {
            await this.productDbEm.transactional(async (manager: EntityManager) => {
            for (const item of (batch as any[])) {
              let product: Product | null = await this.productRepository.findOne({ id: item.productId });
              if ((product != null)) {
                product.inventory = (product.inventory + item.quantity);
                await this.productRepository.getEntityManager().persistAndFlush(product);
              }
              item.status = ReservationStatus.Expired;
              item.save();
            }
          });
          });
          if (mqProducerInstance !== null) {
          await mqProducerInstance.publishInventoryReleased({ reservationId: reservationId, reason: 'Expired' });
        }
          count = (count + 1);
          console.info('released_expired_reservation');
        }
        if ((count > 0)) {
          console.info('cleanup_complete');
        }
        clearTimeout(timeoutId);
        const durationMs = Date.now() - startTime;
        this.logger.log(`job_completed name=ReleaseExpiredReservations duration_ms=${durationMs}`);
        return;
      } catch (error: unknown) {
        clearTimeout(timeoutId);
        lastError = error instanceof Error ? error : new Error(String(error));
        if (attempt < config.maxAttempts) {
          const delay = 1000;
          this.logger.warn(
            `job_retry name=ReleaseExpiredReservations attempt=${attempt} max=${config.maxAttempts}`,
          );
          await new Promise<void>(resolve => setTimeout(resolve, delay));
          continue;
        }
      }
    }

    const durationMs = Date.now() - startTime;
    const message = lastError?.message ?? 'unknown';
    this.logger.error(
      `job_failed name=ReleaseExpiredReservations duration_ms=${durationMs} error=${message}`,
    );
  }


  @Cron(JOB_CONFIGS['UpdatePopularProducts'].schedule, { timeZone: process.env.TZ || 'UTC' })
  async runUpdatePopularProducts(): Promise<void> {
    const config = JOB_CONFIGS['UpdatePopularProducts'];
    const startTime = Date.now();
    this.logger.log('job_started name=UpdatePopularProducts');

    let lastError: Error | undefined;
    for (let attempt = 1; attempt <= config.maxAttempts; attempt++) {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), config.timeoutSeconds * 1000);
      try {
let products: Product[] = await (this.productRepository.getEntityManager() as SqlEntityManager).createQueryBuilder(Product, 'e_product').select('*').where('e_product.status = ?', [ProductStatus.Active]).getResultList();
        for (const product of products) {
          let views: number = ((parseInt(String((await _getRedis().get((String("views:product:") + ':' + String(String(product.id))))) ?? '0'), 10)) ?? 0);
          let score: number = views;
          (await Promise.all([_getRedis().zadd("popular:", score, String(product.id)), _getRedis().expire("popular:", 86400)]))[0];
        }
        console.info('updated_popular_products');
        clearTimeout(timeoutId);
        const durationMs = Date.now() - startTime;
        this.logger.log(`job_completed name=UpdatePopularProducts duration_ms=${durationMs}`);
        return;
      } catch (error: unknown) {
        clearTimeout(timeoutId);
        lastError = error instanceof Error ? error : new Error(String(error));
        if (attempt < config.maxAttempts) {
          const delay = 1000;
          this.logger.warn(
            `job_retry name=UpdatePopularProducts attempt=${attempt} max=${config.maxAttempts}`,
          );
          await new Promise<void>(resolve => setTimeout(resolve, delay));
          continue;
        }
      }
    }

    const durationMs = Date.now() - startTime;
    const message = lastError?.message ?? 'unknown';
    this.logger.error(
      `job_failed name=UpdatePopularProducts duration_ms=${durationMs} error=${message}`,
    );
  }


}
